import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"16、【豫】 坤下震上","description":"周易阐真 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"周易阐真 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"zh/classics/chanzhen/017.md","filePath":"zh/classics/chanzhen/017.md"}'),s={name:"zh/classics/chanzhen/017.md"};function n(c,a,i,o,h,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过，而四时不忒。圣人以顺动，则刑罚清而民服，豫之时义大矣哉！</p></blockquote><h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><p>初六：鸣豫，凶。</p><p>六二：介于石，不终日，贞吉。</p><p>六三：盱豫。悔迟。有悔。</p><p>九四：由豫，大有得。勿疑。朋盍簪。</p><p>六五：贞疾，恒不死。</p><p>上六：冥豫。成有渝，无咎。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。</p><p>豫者，乐也。上震雷，下坤地，是雷出于地，奋发而升，阳气通和，万物无不为之爽畅，豫之象也。</p><p>先王有见于此，知德者，天之所命，为人生之根本，不可不乐于修为，以是作乐以崇其德焉。乐所以和德，德所以成乐。若不崇德而作乐，是谓苦中作乐。惟借乐以和德，其德愈崇；借德以作乐，其乐愈和。德乐相符，是谓真乐，其乐音之殷盛，足以荐上帝、配祖考。盖上帝之所喜者德，祖考之所悦者亦德。荐上帝，以德荐也；配祖考，以德配也。作乐不失其德，是不违其上帝，不忘其祖考。不违上帝，答天也；不忘祖考，报本也。夫人之有生，命受于上帝，形本于祖考。形所以载命，命所以全形，形与命两不相离。报本即是答天，答天即是报本。答天报本，神鬼皆乐，而人焉有不乐？崇德作乐之效有如此，人何乐而不崇德哉!</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>盱，音吁。盍，音合。簪，侧林反。</p><p>豫者，乐也。卦德上震动，下坤顺，顺时而动，动而通顺，故谓豫。此以阴招阳之卦，承上大有而来，大有健明两用，富有日新之道也。富有日新，须要顺时而动，方能成功。若能顺时，则进健得正，用明得当，火候不差，爻铢有准，急缓得法，进退合节，由有为而至无为，自无得而复失之患。其顺动之乐为何如?顺动之象，莫如建侯行师，侯为一国之主，将为众军之主。建侯顺天时，则一国治；行师顺人心，则众军全。心为一身之主，如侯如将也。</p><p>顺动利于建侯行师，即利于正心修身。顺时而动，则利；不顺时而动，则不利。利则得乐，不利则不乐。致乐之道，顺而动之尽矣。</p><p>初六，居豫之初，又在三阴之下，性质本愚，且与小人为伍，自暴自弃，以苦为乐，是谓鸣豫。豫而至鸣，无乐而自为乐，终必入于下愚不移之地，而不得乐。此匪正取凶之乐也。</p><p>六二，无贪无求，乐天知命，如介于石，确然有守，不以外假而伤内真，至于非分之乐，不俟终日，则即去之。此守贞得吉之乐也。</p><p>六三，舍己之乐，仰望他人之乐，是谓盱豫。豫至于盱，未得于人，先失其己，致悔之道。既知盱人无益而速悔，则可无悔。否则，不能悔速，而悔迟，终必有悔，而不得乐。此失正致悔之乐也。</p><p>九四，以一阳而居于群阴之中，不为群阴所惑，且能点化群阴，皆来顺之，是谓由豫大有得也。大得之象，如乱发朋盍而归于一簪，以一御纷，以定止乱，阳气常振，阴气自化，乐何如之。此用刚有得之乐也。</p><p>六五，柔而不刚，孤寂守静，空而不实，如有疾而不能乐矣。然柔而得中，即不能致乐，亦不至招凶，虽有疾而恒不死，不死不活，独守一贞，安于小乘，纵真阳在望，未许我有。此着于顽空无乐也。</p><p>上六，在豫之终，只知顺行其乐，不知逆运其乐，是谓冥豫。豫至于冥，执固不通，顺其所欲之乐，虽乐事已成，必有渝变，乐极生悲，终必自败，与人无咎。此随心所好失乐也。</p><p>然则乐之为道，总在能顺；致乐之道，总在能顺时而动。顺时而动，阳气舒畅，如雷出地外，奋发登天，震惊百里，一切邪魔魍魉，尽皆遁迹，生机不息，大地里黄芽长遍，满世界金花开绽，信步走去，头头是道，乐莫乐于此也。</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
